26	    public void service(@RequestBody OwnerFieldsDto request, Validator validator, Out<OwnerFieldsDto> validated)
27	            throws MissingOwnerFieldsException {
28	        List<String> errors = new ArrayList<>();
29	        normalizeAddress(request);
30	        addIfBlank(errors, "firstName", request.getFirstName());
31	        addIfBlank(errors, "lastName", request.getLastName());
32	        addIfBlank(errors, "address", request.getAddress());
33	        addIfBlank(errors, "city", request.getCity());
