49	    /**
50	     * Email is optional. When absent nothing is done; when present the schema {@code @Email}
51	     * constraint (checked above) has already rejected a syntactically invalid address with a
52	     * {@code 400}, so a value reaching here is valid and is stored and returned lower-cased.
53	     */
54	    private static void normalizeEmail(OwnerFieldsDto request) {
55	        String email = request.getEmail();
56	        if (email != null) {
57	            request.setEmail(email.toLowerCase(java.util.Locale.ROOT));
58	        }
59	    }
