63	     * abbreviations) and write it back onto the request so it is stored and returned in normalized
64	     * form. The structured form is preferred: when {@code addressLine1} normalizes to a non-blank
65	     * value the structured lines are normalized and the flat {@code address} is set to the composed
66	     * value — the normalized {@code addressLine1} with a single space and the normalized
67	     * {@code addressLine2} appended when {@code addressLine2} is present. Otherwise the flat
68	     * {@code address} input is normalized and the structured lines are cleared, keeping earlier
69	     * flat-only owners backward compatible. Running before the blank check means an owner that
70	     * supplies neither form — and so has a blank composed {@code address} — is rejected as an
71	     * {@code address} required-field error (400).
72	     */
73	    private static void normalizeAddress(OwnerFieldsDto request) {
74	        String line1 = AddressNormalizer.normalize(request.getAddressLine1());
75	        if (!line1.isEmpty()) {
76	            String line2 = AddressNormalizer.normalize(request.getAddressLine2());
77	            request.setAddressLine1(line1);
78	            if (line2.isEmpty()) {
79	                request.setAddressLine2(null);
80	                request.setAddress(line1);
81	            }
82	            else {
83	                request.setAddressLine2(line2);
84	                request.setAddress(line1 + " " + line2);
85	            }
86	        }
87	        else {
88	            request.setAddressLine1(null);
89	            request.setAddressLine2(null);
90	            request.setAddress(AddressNormalizer.normalize(request.getAddress()));
91	        }
92	    }
