1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.function.common.Membership;
7	
8	/**
9	 * Step of {@code POST /api/owners} that stamps the owner's numeric {@code membershipLevel},
10	 * applying the household ceiling: a new owner's level cannot exceed one above the current maximum
11	 * membershipLevel among their existing household members. With no existing household member no cap
12	 * applies and the owner keeps the level its own points earn.
13	 *
14	 * <p>The ceiling is evaluated over the household as it currently stands: each existing member sharing
15	 * this owner's {@code householdId} is re-scored with the current household size (this owner's
16	 * {@code householdMemberCount}, set by {@link AssignHouseholdSize}), so a member created when the
17	 * household was smaller still counts toward the ceiling at its current standing. The capped value is
18	 * stored on the owner and returned by the response mapper; {@code membershipPoints} is unaffected.
19	 *
20	 * <p>Runs after {@link AssignHouseholdSize} (which stamps {@code householdId} upstream via
21	 * {@link AssignHousehold} and this owner's {@code householdMemberCount}) and before {@link SaveOwner},
22	 * so the count reflects the existing members plus this owner and the level persists.
23	 */
24	public class AssignMembershipLevel {
25	
26	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
27	        int naturalLevel = Membership.levelOf(owner);
28	        String householdId = owner.getHouseholdId();
29	        Integer householdSize = owner.getHouseholdMemberCount();
30	
31	        int maxExistingLevel = 0;
32	        boolean hasExistingMember = false;
33	        if (householdId != null) {
34	            for (Owner existing : ownerRepository.findAll()) {
35	                if (householdId.equals(existing.getHouseholdId())) {
36	                    hasExistingMember = true;
37	                    maxExistingLevel = Math.max(maxExistingLevel,
38	                            Membership.levelOf(existing, householdSize));
39	                }
40	            }
41	        }
